var CF_NOTES = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
var CF_FLAT = { 'DB':'C#','EB':'D#','GB':'F#','AB':'G#','BB':'A#' };
var CF_CHORDS = [
  { name: '大三和弦', formula: [0,4,7] },
  { name: '小三和弦', formula: [0,3,7] },
  { name: '减三和弦', formula: [0,3,6] },
  { name: '增三和弦', formula: [0,4,8] },
  { name: '挂四和弦 sus4', formula: [0,5,7] },
  { name: '挂二和弦 sus2', formula: [0,2,7] },
  { name: '大七和弦 maj7', formula: [0,4,7,11] },
  { name: '属七和弦 7', formula: [0,4,7,10] },
  { name: '小七和弦 m7', formula: [0,3,7,10] },
  { name: '半减七和弦 m7b5', formula: [0,3,6,10] },
  { name: '减七和弦 dim7', formula: [0,3,6,9] }
];
var CF_SCALES = {
  major: [0,2,4,5,7,9,11],
  minor: [0,2,3,5,7,8,10],
  pentMajor: [0,2,4,7,9],
  pentMinor: [0,3,5,7,10],
  blues: [0,3,5,6,7,10]
};
function cfParseNote(s){
  var u = String(s||'').trim().toUpperCase();
  if(CF_FLAT[u] !== undefined) u = CF_FLAT[u];
  var i = CF_NOTES.indexOf(u);
  return i < 0 ? null : i;
}
function cfParseNotes(text){
  var parts = String(text||'').trim().split(/[\s,]+/).filter(Boolean);
  var out = [];
  for(var i=0;i<parts.length;i++){
    var p = cfParseNote(parts[i]);
    if(p === null) return { error: '无法识别音符：' + parts[i] };
    if(out.indexOf(p) < 0) out.push(p);
  }
  if(out.length < 2) return { error: '至少输入 2 个不同音符' };
  return { pcs: out };
}
function cfDetect(pcs){
  var hits = [];
  for(var r=0;r<pcs.length;r++){
    var root = pcs[r];
    var rel = pcs.map(function(p){ return ((p - root) % 12 + 12) % 12; }).sort(function(a,b){ return a-b; });
    for(var c=0;c<CF_CHORDS.length;c++){
      var f = CF_CHORDS[c].formula.slice().sort(function(a,b){ return a-b; });
      if(rel.length === f.length && rel.every(function(v,i){ return v === f[i]; })){
        hits.push({ root: CF_NOTES[root], name: CF_CHORDS[c].name, inversion: r > 0 });
      }
    }
  }
  return hits;
}
function cfScale(rootPc, type){
  var iv = CF_SCALES[type];
  if(!iv) return null;
  return iv.map(function(s){ return (rootPc + s) % 12; });
}
function cfNames(pcs){ return pcs.map(function(p){ return CF_NOTES[p]; }); }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { CF_NOTES:CF_NOTES, CF_CHORDS:CF_CHORDS, CF_SCALES:CF_SCALES, cfParseNote:cfParseNote, cfParseNotes:cfParseNotes, cfDetect:cfDetect, cfScale:cfScale, cfNames:cfNames };
}
if (typeof window !== 'undefined') {
  window.ChordForgePure = { CF_NOTES:CF_NOTES, CF_CHORDS:CF_CHORDS, CF_SCALES:CF_SCALES, cfParseNote:cfParseNote, cfParseNotes:cfParseNotes, cfDetect:cfDetect, cfScale:cfScale, cfNames:cfNames };
}
